<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
if(empty($_SESSION['admin_id']))redirect('index.php');
require_once dirname(__DIR__).'/private/planning_store.php';
require_once dirname(__DIR__).'/private/waste_widget.php';
$operations=opsReady($pdo);
$day=(string)($_GET['date']??date('Y-m-d'));if(!zgsValidDate($day))$day=date('Y-m-d');
$monday=(new DateTimeImmutable($day,new DateTimeZone('Europe/Berlin')))->modify('monday this week')->format('Y-m-d');
$view=($_GET['view']??'day')==='week'?'week':'day';$back='planner.php?date='.$day.'&view='.$view;
$error=$_SESSION['plan_error']??'';unset($_SESSION['plan_error']);$notice=$_SESSION['plan_notice']??'';unset($_SESSION['plan_notice']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 checkCsrf();try{
  $action=(string)($_POST['action']??'');$id=(int)($_POST['task_id']??0);
  if($action==='generate'){$generated=zgsGenerateDueTasks($pdo,date('Y-m-d'));$_SESSION['plan_notice']=$generated['created'].' fällige Aufgaben erstellt.'.($generated['backlog_jobs']?' Rückstand noch vorhanden: erneut begrenzt aktualisieren.':' Bereits vorhandene Aufgaben bleiben erhalten.');}
  elseif($action==='preview'){$token=planSaveProposal($pdo,(int)$_SESSION['admin_id'],$monday,($_POST['scope']??'week')==='day'?$day:null);redirect($back.'&proposal='.$token);}
  elseif($action==='apply'){planApply($pdo,(int)$_SESSION['admin_id'],(string)($_POST['token']??''));if(($_SESSION['planning_proposal_token']??'')===($_POST['token']??''))unset($_SESSION['planning_proposal_token']);$_SESSION['plan_notice']='Vorschlag übernommen; manuelle Sperren und erledigte Aufgaben erhalten.';}
  elseif($action==='toggle'){if($operations){$q=$pdo->prepare('SELECT done FROM tasks WHERE id=?');$q->execute([$id]);$done=$q->fetchColumn();if($done===false)throw new RuntimeException('Aufgabe nicht gefunden.');opsSetDone($pdo,(int)$_SESSION['admin_id'],$id,isset($_POST['done'])?$_POST['done']==='1':!(bool)$done,opsVersion($_POST));}else $pdo->prepare('UPDATE tasks SET done=1-done WHERE id=?')->execute([$id]);}
  elseif($action==='task'){
   $args=planValidateTask($_POST);$pid=(int)($_POST['property_id']??0);
   if($pid){$s=$pdo->prepare('SELECT id FROM properties WHERE id=?');$s->execute([$pid]);if(!$s->fetchColumn())throw new InvalidArgumentException('Objekt unbekannt.');}
   if($operations)opsSaveTask($pdo,(int)$_SESSION['admin_id'],$args,$pid,$id,isset($_POST['unlock']),opsVersion($_POST));
   else if($id)$pdo->prepare('UPDATE tasks SET title=?,due_date=?,notes=?,duration_minutes=?,start_time=?,priority=?,sort_order=?,window_start=?,window_end=?,property_id=?,plan_locked=? WHERE id=?')->execute([...$args,$pid?:null,isset($_POST['unlock'])?0:1,$id]);
   else $pdo->prepare('INSERT INTO tasks(title,due_date,notes,duration_minutes,start_time,priority,sort_order,window_start,window_end,property_id,plan_locked) VALUES(?,?,?,?,?,?,?,?,?,?,1)')->execute([...$args,$pid?:null]);
  }elseif($action==='appointment'){
   $d=(string)($_POST['appointment_day']??'');$start=(string)($_POST['appointment_start']??'');$end=(string)($_POST['appointment_end']??'');$title=trim((string)($_POST['appointment_title']??''));$address=trim((string)($_POST['address']??''));
   if(!zgsValidDate($d)||planMinute($start)>=planMinute($end)||$title===''||mb_strlen($title)>190||mb_strlen($address)>255)throw new InvalidArgumentException('Termin: Datum, Beschreibung und Ende nach Beginn erforderlich.');
   if($operations)opsSaveAppointment($pdo,(int)$_SESSION['admin_id'],$_POST,(int)($_POST['appointment_id']??0));else $pdo->prepare('INSERT INTO planning_appointments(day,start_time,end_time,title,address) VALUES(?,?,?,?,?)')->execute([$d,$start,$end,$title,$address]);
  }elseif($action==='remove_appointment'){if($operations)opsCancelAppointment($pdo,(int)$_SESSION['admin_id'],(int)($_POST['appointment_id']??0),opsVersion($_POST));else $pdo->prepare('DELETE FROM planning_appointments WHERE id=?')->execute([(int)($_POST['appointment_id']??0)]);}
  elseif($action==='settings'){
   $start=(string)($_POST['day_start']??'');$target=(string)($_POST['target']??'');$warn=(string)($_POST['warning']??'');$buffer=filter_var($_POST['buffer']??'',FILTER_VALIDATE_INT);$destination=trim((string)($_POST['destination']??''));
   if(planMinute($start)>=planMinute($target)||planMinute($target)>=planMinute($warn)||$buffer===false||$buffer<0||$buffer>120||mb_strlen($destination)>190)throw new InvalidArgumentException('Start < Ziel < Warnschwelle; Puffer 0–120 Minuten.');
   $v1Settings=gszV1Ready($pdo);if($v1Settings){$mask=filter_var($_POST['workdays_mask']??31,FILTER_VALIDATE_INT);$cap=(string)($_POST['capacity_end_time']??$warn);if(!$mask||$mask<1||$mask>127||planMinute($cap)<planMinute($target))throw new InvalidArgumentException('Arbeitstage/Kapazitätsende prüfen.');}$pdo->beginTransaction();
   $pdo->prepare('UPDATE planning_settings SET start_time=?,target_time=?,warning_time=?,buffer_minutes=?,evening_destination=? WHERE id=1')->execute([$start,$target,$warn,$buffer,$destination]);if($v1Settings)$pdo->prepare('UPDATE planning_settings SET workdays_mask=?,capacity_end_time=? WHERE id=1')->execute([$mask,$cap]);$pdo->commit();
  }elseif($action==='day_start'){
   $start=(string)($_POST['day_start']??'');planMinute($start);$pdo->prepare('INSERT INTO planning_days(day,start_time) VALUES(?,?) ON DUPLICATE KEY UPDATE start_time=VALUES(start_time)')->execute([$day,$start]);
  }else throw new InvalidArgumentException('Unbekannte Aktion.');
 if(in_array($action,['toggle','task','appointment','remove_appointment','generate'],true))gszSuggestWeek($pdo,(int)$_SESSION['admin_id']);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['plan_error']=$e instanceof PDOException?'Planung nicht verfügbar. Migration und Datenbank prüfen.':$e->getMessage();}
 redirect($back);
}
$data=null;$proposal=null;$plan=null;
try{
 $data=planLoad($pdo);$starts=array_column($data['starts'],'start_time','day');
 if(isset($_GET['proposal'])){$s=$pdo->prepare('SELECT * FROM planning_proposals WHERE token=? AND admin_id=?');$s->execute([(string)$_GET['proposal'],$_SESSION['admin_id']]);$proposal=$s->fetch();if($proposal&&!empty($proposal['applied_at'])){$notice.=' Vorschlag bereits übernommen; aktueller Plan wird angezeigt.';$proposal=null;}if($proposal)$plan=json_decode($proposal['payload'],true,512,JSON_THROW_ON_ERROR)['plan'];}
 if(!$plan){$group=[];foreach($data['tasks'] as $t)if($t['due_date']>=$monday&&$t['due_date']<=planDate($monday,6))$group[$t['due_date']][]=$t;
  $plan=['days'=>[],'warnings'=>[],'unplaced'=>array_values(array_filter($data['tasks'],fn($t)=>!$t['done']&&(!$t['due_date']||$t['due_date']<$monday)))];
  for($i=0;$i<7;$i++){$d=planDate($monday,$i);$tasks=$group[$d]??[];usort($tasks,fn($a,$b)=>[(int)($a['sort_order']?:$a['planned_order']),$a['start_time']??'99:99',$a['id']]<=>[(int)($b['sort_order']?:$b['planned_order']),$b['start_time']??'99:99',$b['id']]);$apps=array_values(array_filter($data['appointments'],fn($a)=>$a['day']===$d));$plan['days'][$d]=planTimeline($tasks,$apps,$data['settings'],$starts[$d]??$data['settings']['start_time']);$plan['days'][$d]['appointments']=$apps;}
 }
}catch(Throwable $e){$error=$e instanceof PDOException?'Planung benötigt die Phase-2-Migration.':$e->getMessage();}
// Reuse a confirmed route only while its complete business snapshot is current.
if($data&&!$proposal&&$view==='day'){
 try{require_once dirname(__DIR__).'/private/routing_store.php';$confirmed=routeConfirmedDay($pdo,$day);
  if($confirmed&&empty($confirmed['stale'])){$route=$confirmed['route'];$apps=$plan['days'][$day]['appointments'];$plan['days'][$day]=$route['timeline'];$plan['days'][$day]['appointments']=$apps;$plan['days'][$day]['route_metadata']=$route;$plan['days'][$day]['warnings']=array_merge($plan['days'][$day]['warnings'],$route['warnings']);}
  elseif($confirmed)$notice.=' Bestätigte Route inzwischen geändert/veraltet; Route neu berechnen.';
 }catch(PDOException $e){} // Phase-2-only regression fixtures have no routing tables.
}
$properties=$pdo->query('SELECT id,name FROM properties ORDER BY name LIMIT 500')->fetchAll();
function planHidden(string $action,int $id=0):void{echo '<input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="task_id" value="'.$id.'">';}
function planTaskForm(array $t,array $properties,string $day):void { ?>
<form method="post"><?php planHidden('task',(int)($t['id']??0));?><?php if(isset($t['row_version'])):?><input type="hidden" name="row_version" value="<?=(int)$t['row_version']?>"><?php endif?><label>Aufgabe<input name="title" maxlength="190" required value="<?=e($t['title']??'')?>"></label><label>Datum<input type="date" name="due_date" required value="<?=e($t['due_date']??$day)?>"></label><label>Objekt<select name="property_id"><option value="">Ohne Objekt</option><?php foreach($properties as $p):?><option value="<?=(int)$p['id']?>" <?=(int)($t['property_id']??0)===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach?></select></label>
<label>Dauer in Minuten (leer = unbestimmt)<input type="number" name="duration_minutes" min="1" max="1440" value="<?=e((string)($t['duration_minutes']??''))?>"></label><label>Feste Uhrzeit (optional)<input type="time" name="start_time" value="<?=e(substr($t['start_time']??'',0,5))?>"></label><label>Reihenfolge (0 = automatisch)<input type="number" name="sort_order" min="0" max="9999" value="<?=(int)($t['sort_order']??0)?>"></label><label>Priorität<select name="priority"><?php foreach(['urgent','high','normal','low'] as $v):?><option <?=($t['priority']??'normal')===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select></label><label>Frühestens<input type="date" name="window_start" value="<?=e($t['window_start']??'')?>"></label><label>Spätestens<input type="date" name="window_end" value="<?=e($t['window_end']??'')?>"></label><label>Optionale Notiz<textarea name="notes" maxlength="5000"><?=e($t['notes']??'')?></textarea></label><label><input type="checkbox" name="unlock" value="1"> Tag wieder zur automatischen Verteilung freigeben (Uhrzeit/Reihenfolge dafür leeren).</label><button>Aufgabe speichern</button></form>
<?php }
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Heute und Wochenplanung · GSZ</title><link rel="stylesheet" href="assets.css"><link rel="stylesheet" href="planning.css"></head><body><main><header><a href="index.php">← Zentrale</a><a href="recurring.php">Regelaufgaben</a></header><h1>Heute und Wochenplanung</h1><p><a href="route.php?date=<?=e($day)?>">Route optimieren →</a> · <a href="waste.php">Müllkalender</a></p><?php wasteWidget($pdo,$day);?><nav class="actions"><a href="planner.php">Heute</a><a href="?date=<?=e($day)?>&amp;view=day">Tag</a><a href="?date=<?=e($day)?>&amp;view=week">Woche</a><a href="?date=<?=e(planDate($day,$view==='day'?-1:-7))?>&amp;view=<?=e($view)?>">← Zurück</a><a href="?date=<?=e(planDate($day,$view==='day'?1:7))?>&amp;view=<?=e($view)?>">Weiter →</a></nav><form method="get"><label>Datum<input type="date" name="date" value="<?=e($day)?>"></label><button>Öffnen</button></form>
<?php if($error):?><p class="error" role="alert"><?=e($error)?></p><?php endif?><?php if($notice):?><p role="status"><?=e($notice)?></p><?php endif?>
<p><a href="appointments.php">Termine bearbeiten / Erinnerungen</a> · <a href="workers.php">Mitarbeiter / Subunternehmer</a></p><p>Gebietsbasierte Heuristik, keine optimierte Route. Keine Fahrtdaten vorhanden. Puffer sind manuelle Schätzwerte; bei 0 Minuten fehlt jede Fahrzeitreserve. Keine eigenständig erfundenen Feiertags-/Abfalltermine.</p>
<?php if($data):?><form method="post"><?php planHidden('generate');?><button>Fällige Regelaufgaben aktualisieren</button></form><p>Ohne eingerichteten Cron einmal täglich aktualisieren. Reines Öffnen speichert keine neuen Aufgaben.</p><div class="actions"><form method="post"><?php planHidden('preview');?><input type="hidden" name="scope" value="week"><button>Wochenvorschau erzeugen</button></form><form method="post"><?php planHidden('preview');?><input type="hidden" name="scope" value="day"><button>Tag optimieren – Vorschau</button></form></div>
<?php if($proposal):?><section class="card"><h2>Vorschau – noch nicht übernommen</h2><p>Fälligkeit, Priorität, vorhandene Kapazität und Adressgruppen bestimmen die Vorschläge. Feste Termine und manuelle Sperren bleiben erhalten. Angezeigte Änderungen erst durch Bestätigung übernehmen. Nicht untergebrachte Bestandsaufgaben behalten ihre bisherige Fälligkeit und benötigen eine manuelle Klärung; ein Teilvorschlag beseitigt diese Konflikte nicht. Für manuelle Korrekturen Vorschau verlassen, Aufgabe bearbeiten und neu berechnen.</p><form method="post"><?php planHidden('apply');?><input type="hidden" name="token" value="<?=e($proposal['token'])?>"><button>Vorschlag bestätigen und übernehmen</button></form><a href="<?=e($back)?>">Vorschau verwerfen</a></section><?php endif?>
<?php foreach($plan['warnings'] as $w):?><p class="error"><?=e($w)?></p><?php endforeach?>
<div class="planning-days"><?php foreach($plan['days'] as $d=>$daily):if(!$proposal&&$view==='day'&&$d!==$day)continue;?><section class="card"><h2><?=e((['','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'][(int)(new DateTimeImmutable($d))->format('N')]).', '.(new DateTimeImmutable($d))->format('d.m.Y'))?></h2><p>Start <?=e(substr($starts[$d]??$data['settings']['start_time'],0,5))?> · Arbeitsminuten <?=$daily['minutes']?> · <?=isset($daily['route_metadata'])&&$daily['route_metadata']['source']?'Routing-Fahrminuten':'geschätzter Puffer'?> <?=$daily['buffer']?> Min. · Ende <?=e(planTime($daily['end']))?><?php if(str_contains(implode(' ',$daily['warnings']),'unbestimmt')):?> (unvollständig)<?php endif?></p>
<?php if(isset($daily['route_metadata'])):?><p><?=e($daily['route_metadata']['mode'])?> · <?=e($daily['route_metadata']['source']??'Keine Routingdaten')?> · <?=e($daily['route_metadata']['timestamp']??'manuelle Schätzwerte')?> · <a href="route.php?date=<?=e($day)?>">Fahrabschnitte und Zielfahrt</a></p><?php endif?><?php foreach($daily['warnings'] as $w):?><p class="error"><?=e($w)?></p><?php endforeach?>
<?php foreach($daily['appointments'] as $a):?><article class="appointment"><strong>Fixtermin <?=e(substr($a['start_time'],0,5).'–'.substr($a['end_time'],0,5))?> · <?=e($a['title'])?></strong><p><?=e($a['address'])?></p><?php if(!$proposal):?><form method="post"><?php planHidden('remove_appointment'); if(isset($a['row_version'])):?><input type="hidden" name="row_version" value="<?=(int)$a['row_version']?>"><?php endif?><input type="hidden" name="appointment_id" value="<?=(int)$a['id']?>"><button>Termin entfernen</button></form><?php endif?></article><?php endforeach?>
<?php foreach($daily['rows'] as $row):$t=$row['task'];?><article class="task-row"><h3><?=e($row['start']===null?'Erledigt':planTime($row['start']).'–'.($row['end']===null?'offen':planTime($row['end'])))?> · <?=e($t['title'])?></h3><p><?=e($t['property_name']??'Ohne Objekt')?> · <?=e($t['address']??'')?> · <?=$row['duration']===null?'Dauer unbestimmt':$row['duration'].' Min.'?> · Fahrabschnitt/Puffer <?=$row['buffer']?> Min.</p><p><?=planFixed($t)?'Termin/Reihenfolge geschützt':'Flexibel planbar'?></p><?php if($proposal):?><p>Änderung: <?=e($t['due_date']??'ohne Termin')?> → <?=e($d)?>; vorgeschlagene Reihenfolge wie angezeigt.</p><?php endif?><?php foreach($row['warnings'] as $w):?><p class="error"><?=e($w)?></p><?php endforeach?><p><?=nl2br(e($t['notes']??''))?></p>
<?php if(!empty($t['address'])):?><a href="https://www.google.com/maps/search/?api=1&amp;query=<?=e(rawurlencode($t['address']))?>" target="_blank" rel="noopener noreferrer">Navigation öffnen</a><?php endif?>
<?php if(!$proposal&&$t['id']):?><form method="post"><?php planHidden('toggle',(int)$t['id']); if(isset($t['row_version'])):?><input type="hidden" name="row_version" value="<?=(int)$t['row_version']?>"><input type="hidden" name="done" value="<?=$t['done']?'0':'1'?>"><?php endif?><button><?=$t['done']?'Wieder öffnen':'✓ Erledigt'?></button></form><details><summary>Bearbeiten / verschieben / Reihenfolge / Notiz</summary><?php planTaskForm($t,$properties,$day);?></details><?php if($operations):?><p><a href="task.php?id=<?=(int)$t['id']?>">Notiz, Zuordnung und Verlauf</a></p><?php endif?><?php endif?></article><?php endforeach?></section><?php endforeach?></div>
<?php if($plan['unplaced']):?><section class="card"><h2>Nicht eingeplant / überfällig / ohne Datum</h2><?php foreach($plan['unplaced'] as $t):?><p><?=e($t['title'])?> · <?=e($t['due_date']??'ohne Datum')?> · <?=e($t['scheduled_for']??'manuell')?></p><?php if($t['id']&&!$proposal):?><details><summary>Manuell zuordnen</summary><?php planTaskForm($t,$properties,$day);?></details><?php endif?><?php endforeach?></section><?php endif?>
<details class="card"><summary>Spontane Aufgabe hinzufügen</summary><?php planTaskForm([],$properties,$day);?></details>
<details class="card"><summary>Fixtermin hinzufügen</summary><form method="post"><?php planHidden('appointment');?><label>Datum<input type="date" name="appointment_day" value="<?=e($day)?>" required></label><label>Von<input type="time" name="appointment_start" required></label><label>Bis<input type="time" name="appointment_end" required></label><label>Beschreibung<input name="appointment_title" maxlength="190" required></label><label>Adresse optional<input name="address" maxlength="255"></label><button>Fixtermin speichern</button></form></details>
<details class="card"><summary>Planungseinstellungen</summary><form method="post"><?php planHidden('settings');if(gszV1Ready($pdo)):?><input type="hidden" name="workdays_mask" value="<?=(int)$data['settings']['workdays_mask']?>"><input type="hidden" name="capacity_end_time" value="<?=e(substr($data['settings']['capacity_end_time'],0,5))?>"><p><a href="settings.php">Arbeitstage und Kapazitätsende bearbeiten</a></p><?php endif?><label>Standardstart<input type="time" name="day_start" value="<?=e(substr($data['settings']['start_time'],0,5))?>" required></label><label>Zielende<input type="time" name="target" value="<?=e(substr($data['settings']['target_time'],0,5))?>" required></label><label>Warnschwelle<input type="time" name="warning" value="<?=e(substr($data['settings']['warning_time'],0,5))?>" required></label><label>Geschätzter Puffer je Objektwechsel<input type="number" name="buffer" min="0" max="120" value="<?=(int)$data['settings']['buffer_minutes']?>"></label><label>Abendziel (ohne Routenberechnung)<input name="destination" maxlength="190" value="<?=e($data['settings']['evening_destination'])?>" placeholder="Zuhause oder Fitnessstudio"></label><button>Einstellungen speichern</button></form><form method="post"><?php planHidden('day_start');?><label>Abweichender Start nur für <?=e($day)?> (z.B. Uni länger)<input type="time" name="day_start" required></label><button>Tagesstart speichern</button></form></details><?php endif?></main></body></html>
